lfs_size_t read_size = lfs_max(hint, size);
    uint8_t *read_buf = (uint8_t *)lfs_cache_get_buffer(rcache);
    lfs_size_t read_off = 0;

    while (read_off < size) {
        lfs_size_t chunk = lfs_max(read_size, size - read_off);
        if (chunk > lfs_cache_get_size(rcache)) {
            chunk = lfs_cache_get_size(rcache);
        }

        int err = lfs_cache_read(lfs, rcache, block, off + read_off, read_buf, chunk);
        if (err < 0) {
            return err;
        }

        lfs_size_t cmp_size = lfs_max(0, size - read_off);
        if (cmp_size > chunk) {
            cmp_size = chunk;
        }

        int cmp = std::memcmp(read_buf, (const uint8_t *)buffer + read_off, cmp_size);
        if (cmp != 0) {
            return cmp;
        }

        read_off += cmp_size;
    }

    return 0; // LFS_CMP_EQ

